  @doc group: "Preview"
  @doc ~S"""
  A form-associated v3 preview of `Carbon.multi_select`.

  Identical to `Carbon.multi_select` in markup, styling and events. The only
  difference is that it participates in its form natively through
  `ElementInternals` instead of the deprecated `formdata` event, so
  `<label for>`, `form.elements`, `form.reset()` and `<fieldset disabled>` all
  work as they do for a native control.

  Submits the same joined `value` string the v2 component does, so the
  wire format is unchanged. Emitting one entry per selection would be a
  deliberate API change and is tracked in the migration guide.

  Renders the Carbon `preview multi select` web component.

  ## Example

  ```heex
  <Carbon.preview_multi_select id="my-preview-multi-select" on_multi_select_beingselected="my_event">
    ...
  </Carbon.preview_multi_select>
  ```

  Child content is rendered inside the component. To fill a named slot of the
  component, set `slot="name"` on the child element.

  ## Events

  Each `on_*` attribute takes the name of a LiveView event and requires an `id`.
  The LiveView receives `%{"detail" => ..., "value" => ..., "id" => ...}`.

    * `on_multi_select_beingselected` - The custom event fired before a multi select item is selected upon a user gesture. Cancellation of this event stops changing the user-initiated selection.
    * `on_multi_select_selected` - The custom event fired after a multi select item is selected upon a user gesture.
    * `on_multi_select_beingtoggled` - The custom event fired before the open state of this multi select is toggled upon a user gesture. Cancellation of this event stops the user-initiated toggling.
    * `on_multi_select_toggled` - The custom event fired after the open state of this multi select is toggled upon a user gesture.
    * `on_dropdown_beingselected` - The custom event fired before a dropdown item is selected upon a user gesture. Cancellation of this event stops changing the user-initiated selection.
    * `on_dropdown_beingtoggled` - The custom event fired before the open state of this dropdown is toggled upon a user gesture. Cancellation of this event stops the user-initiated toggling.
    * `on_dropdown_selected` - The custom event fired after a dropdown item is selected upon a user gesture.
    * `on_dropdown_toggled` - The custom event fired after the open state of this dropdown is toggled upon a user gesture.
  """
  attr :rest, :global, doc: "any additional HTML attributes, e.g. `class`, `id`, `slot`, `phx-*`"
  attr :filterable, :any, default: nil, doc: ""

  attr :autocomplete, :string,
    default: nil,
    doc:
      "The native `autocomplete` attribute for the filterable input. Carbon default: `\"off\"`."

  attr :clear_selection_label, :string,
    default: nil,
    doc: "The `aria-label` attribute for the icon to clear selection. Carbon default: `\"\"`."

  attr :clear_selection_description, :string,
    default: nil,
    doc:
      "Specify the text that should be read for screen readers that describes total items selected Carbon default: `\"Total items selected: \"`."

  attr :clear_selection_text, :string,
    default: nil,
    doc:
      "Specify the text that should be read for screen readers to clear selection. Carbon default: `\"To clear selection, press Delete or Backspace.\"`."

  attr :locale, :string,
    default: nil,
    doc:
      "Specify the locale of the control. Used for the default compareItems used for sorting the list of items in the control. Carbon default: `\"en\"`."

  attr :select_all, :boolean,
    default: nil,
    doc: "Enables rendering of a “Select all” multi-select-item Carbon default: `false`."

  attr :selection_feedback, :any,
    values: ["fixed", "top", "top-after-reopen"],
    doc:
      "Specify feedback (mode) of the selection. `top`: selected item jumps to top `fixed`: selected item stays at it's position `top-after-reopen`: selected item jump to top after reopen dropdown Carbon default: `\"top-after-reopen\"`."

  attr :aria_label, :string,
    default: nil,
    doc:
      "'aria-label' of the ListBox component. Specify a label to be read by screen readers on the container node Carbon default: `\"\"`."

  attr :direction, :any,
    values: ["top", "bottom"],
    doc:
      "Specify the direction of the dropdown. Can be either top or bottom. Carbon default: `\"bottom\"`."

  attr :autoalign, :any,
    default: nil,
    doc:
      "Specify whether auto-align is enabled. Defaults to `true` when `enable-v12-autoalign` is enabled, and to `false` otherwise."

  attr :disabled, :boolean,
    default: nil,
    doc: "`true` if this dropdown should be disabled. Carbon default: `false`."

  attr :helper_text, :string, default: nil, doc: "The helper text. Carbon default: `\"\"`."

  attr :hide_label, :boolean,
    default: nil,
    doc: "Specify whether the title text should be hidden or not Carbon default: `false`."

  attr :invalid_text, :string,
    default: nil,
    doc: "Message which is displayed if the value is invalid. Carbon default: `\"\"`."

  attr :title_text, :string,
    default: nil,
    doc:
      "Provide the title text that will be read by a screen reader when visiting this control Carbon default: `\"\"`."

  attr :name, :string,
    default: nil,
    doc: "Name for the dropdown in the `FormData` Carbon default: `\"\"`."

  attr :open, :boolean,
    default: nil,
    doc: "`true` if this dropdown should be open. Carbon default: `false`."

  attr :read_only, :boolean,
    default: nil,
    doc: "Whether or not the Dropdown is readonly Carbon default: `false`."

  attr :is_fluid, :boolean,
    default: nil,
    doc: "Specify whether the dropdown is fluid or not Carbon default: `false`."

  attr :size, :any,
    values: ["xs", "sm", "md", "lg"],
    doc: "Dropdown size. Carbon default: `\"md\"`."

  attr :toggle_label_closed, :string,
    default: nil,
    doc:
      "The `aria-label` attribute for the UI indicating the closed state. Carbon default: `\"\"`."

  attr :toggle_label_open, :string,
    default: nil,
    doc:
      "The `aria-label` attribute for the UI indicating the open state. Carbon default: `\"\"`."

  attr :label, :string,
    default: nil,
    doc:
      "Generic label that will be used as the textual representation of what this field is for Carbon default: `\"\"`."

  attr :type, :any,
    values: ["", "inline"],
    doc: "`true` if this dropdown should use the inline UI variant. Carbon default: `\"\"`."

  attr :warn, :boolean,
    default: nil,
    doc: "Specify whether the control is currently in warning state Carbon default: `false`."

  attr :warn_text, :string,
    default: nil,
    doc:
      "Provide the text that is displayed when the control is in warning state Carbon default: `\"\"`."

  attr :invalid, :boolean,
    default: nil,
    doc: "`true` to show the UI of the invalid state. Carbon default: `false`."

  attr :required, :boolean,
    default: nil,
    doc: "`true` if the value is required. Carbon default: `false`."

  attr :required_validity_message, :string,
    default: nil,
    doc:
      "The special validity message for `required`. Carbon default: `\"Please fill out this field.\"`."

  attr :validity_message, :string,
    default: nil,
    doc: "The validity message. Carbon default: `\"\"`."

  attr :value, :string,
    default: nil,
    doc: "The value of the selected item. Carbon default: `\"\"`."

  attr :on_multi_select_beingselected, :string,
    default: nil,
    doc:
      "LiveView event name, sent when the component emits its \"multi select beingselected\" event. The custom event fired before a multi select item is selected upon a user gesture. Cancellation of this event stops changing the user-initiated selection."

  attr :on_multi_select_selected, :string,
    default: nil,
    doc:
      "LiveView event name, sent when the component emits its \"multi select selected\" event. The custom event fired after a multi select item is selected upon a user gesture."

  attr :on_multi_select_beingtoggled, :string,
    default: nil,
    doc:
      "LiveView event name, sent when the component emits its \"multi select beingtoggled\" event. The custom event fired before the open state of this multi select is toggled upon a user gesture. Cancellation of this event stops the user-initiated toggling."

  attr :on_multi_select_toggled, :string,
    default: nil,
    doc:
      "LiveView event name, sent when the component emits its \"multi select toggled\" event. The custom event fired after the open state of this multi select is toggled upon a user gesture."

